    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    # Try to find k cycles with representatives
    visited = [False] * (n + 1)
    cycles = []

    def dfs_find_cycle(start):
        """DFS to find a cycle starting from start node."""
        path = [start]
        parent = {start: -1}
        seen = {start}
        stack = [start]

        while stack:
            u = stack[-1]
            for v in adj[u]:
                if v == parent.get(u, -1):
                    continue

                if v in seen:
                    # Found back edge, cycle detected
                    idx = path.index(v)
                    cycle = path[idx:]
                    if len(cycle) >= 3:
                        # Find a representative (unvisited vertex in cycle)
                        found_rep = False
                        for node in set(cycle):
                            if not visited[node]:
                                visited[node] = True
                                found_rep = True
                                break

                        if found_rep:
                            cycles.append(cycle)
                            return True
                else:
                    seen.add(v)
                    parent[v] = u
                    stack.append(v)
                    path.append(v)

            # Pop backtracked node if no children left
            if path:
                path.pop()
            stack.pop()

        return False

    # Find k cycles
    for i in range(1, n + 1):
        if not visited[i]:
            dfs_find_cycle(i)
            if len(cycles) >= k:
                break

    # If enough cycles found, output them
    if len(cycles) >= k:
        result = ["CYCLES"]
        for cycle in cycles[:k]:
            result.append(str(len(cycle)))
            result.append(" ".join(map(str, cycle)))
        return "\n".join(result)

    # Otherwise, search for a long path using DFS with backtracking
    visited_path = [False] * (n + 1)
    current_path = []
    min_len = n // k

    def dfs_path(u, depth):
        if depth >= min_len:
            return True

        visited_path[u] = True
        current_path.append(u)

        for v in adj[u]:
            if not visited_path[v]:
                if dfs_path(v, depth + 1):
                    return True

        # Backtrack
        current_path.pop()
        visited_path[u] = False

        return False

    for start in range(1, n + 1):
        if not visited_path[start]:
            if dfs_path(start, 1):
                result = ["PATH"]
                result.append(str(len(current_path)))
                result.append(" ".join(map(str, current_path)))
                return "\n".join(result)

    return "-1"

