def solve_2sat(n, m, clauses):
    """
    Solves 2-SAT given n clauses with each variable appearing at most twice.
    Returns (satisfiable, assignment) where assignment is a list of 0/1 values.
    """
    # Node representation: variable i -> node 2*i for x_i, node 2*i+1 for ¬x_i
    num_nodes = 2 * m

    # Build implication graph
    graph = [[] for _ in range(num_nodes)]

    for clause in clauses:
        k = len(clause)
        # For clause (l1 ∨ l2 ∨ ... ∨ lk), add implications: 
        # ¬li → lj for all i ≠ j
        for i in range(k):
            node_i = get_node_index(clause[i])
            for j in range(k):
                if i != j:
                    node_j = get_node_index(clause[j])
                    graph[node_i ^ 1].append(node_j)  # ¬li → lj

    # Tarjan's algorithm to find SCCs
    ids = [-1] * num_nodes
    low = [0] * num_nodes
    stack = []
    on_stack = [False] * num_nodes
    scc_id = [-1] * num_nodes
    id_counter = 0
    scc_count = 0

    def dfs(u):
        nonlocal id_counter, scc_count
        ids[u] = low[u] = id_counter
        id_counter += 1
        stack.append(u)
        on_stack[u] = True

        for v in graph[u]:
            if ids[v] == -1:
                dfs(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], ids[v])

        if ids[u] == low[u]:
            while stack:
                v = stack.pop()
                on_stack[v] = False
                scc_id[v] = scc_count
                if v == u:
                    break
            scc_count += 1

    for i in range(num_nodes):
        if ids[i] == -1:
            dfs(i)

    # Check satisfiability: ¬x and x in same SCC means unsatisfiable
    for i in range(m):
        node_pos = 2 * i
        node_neg = 2 * i + 1
        if scc_id[node_pos] == scc_id[node_neg]:
            return (False, None)

    # Construct assignment using topological order
    # Node with higher component (in reverse topological order) gets ≤
    assignment = [0] * m
    for i in range(m):
        node_neg = 2 * i + 1
        node_pos = 2 * i
        if scc_id[node_neg] > scc_id[node_pos]:
            assignment[i] = 1  # ¬x_i is true, so x_i is false
        else:
            assignment[i] = 0  # x_i is true

    return (True, assignment)

def get_node_index(literal):
    """Convert literal (positive or negative value) to node index."""
    var_idx = abs(literal) - 1
    if literal > 0:
        return 2 * var_idx  # x_i
    else:
        return 2 * var_idx + 1  # ¬x_i

