class FlowNetwork:
    def __init__(self, n):
        self.n = n
        self.source = 0
        self.sink = 2 * n + 1
        self.capacity = {}
        self.flow = {}
        self.graph = {}
        for i in range(self.source + 1, self.sink):
            self.capacity[i] = {}
            self.flow[i] = {}
            self.graph[i] = []

    def add_edge(self, u, v, capacity):
        if u not in self.capacity:
            self.capacity[u] = {}
            self.flow[u] = {}
            self.graph[u] = []
        if v not in self.capacity:
            self.capacity[v] = {}
            self.flow[v] = {}
            self.graph[v] = []

        self.capacity[u][v] = self.capacity[u].get(v, 0) + capacity
        self.capacity[v][u] = self.capacity[v].get(u, 0)

        self.flow[u][v] = self.flow[u].get(v, 0)
